import { expireSwrCache } from '@workspace/api';
import type { SwrCacheKey } from '@workspace/api';

/**
 * Ключ кэша портальных настроек приложения.
 *
 * Приложение в имени обязательно: `event-sales` и `event-service` в проде
 * живут на одном origin (`/sales` и `/service`) и делят браузерное
 * хранилище — настройки у них разные, ячейка должна быть разной.
 */
const APP_CONFIG_CACHE_NAME = 'event-sales:app-config';

/**
 * Версия схемы значения. Поднимать, когда меняется ФОРМА ответа бэка
 * (`/app-settings/event-sales`), а не когда добавляется очередной ключ:
 * лишние ключи thunk и так отбрасывает по реестру `DOMAIN_CONFIG_KEYS`.
 *
 * v2 — рядом со значениями приехал признак `storedKeys` (какие ключи
 * реально заданы на портале). Запись кэшируется ЦЕЛИКОМ, вместе с
 * признаком, иначе правило «применяем только заданное» начало бы врать
 * сразу после первого попадания в кэш. Записи v1 признака не содержат:
 * без подъёма версии первый старт после деплоя уходил бы по ним на
 * запасной путь для старого бэка (безопасно, но лишний рейс) — версия
 * делает их нечитаемыми, и фрейм сразу идёт в сеть.
 */
export const APP_CONFIG_CACHE_VERSION = 2;

/**
 * Настройки считаются протухшими СРАЗУ — «из кэша мгновенно, обновление
 * тихо в фоне» в чистом виде.
 *
 * Почему не сутки, как у слепка портала: слепок меняется при install полей,
 * то есть считаные разы в год, а настройки — это ровно тот рычаг, который
 * владелец дёргает в админке и тут же идёт проверять во фрейме (включил
 * анкету — жду вопросы). Суточное окно означало бы «эффект будет завтра».
 *
 * Платы за это нет: ответ крошечный, запрос уходит в фоне и НИЧЕГО не
 * блокирует. Ускорение первого экрана даёт сам кэш: `isConfigFetched`
 * поднимается по кэшу за миллисекунды, а не после сетевого ответа, и
 * `waitForAppConfig` (до 1.5 с) перестаёт держать первый запрос дел.
 */
export const APP_CONFIG_STALE_AFTER_MS = 0;

/** Ключ записи: приложение + домен + версия схемы. */
export const getAppConfigCacheKey = (domain: string): SwrCacheKey => ({
    name: APP_CONFIG_CACHE_NAME,
    domain,
    version: APP_CONFIG_CACHE_VERSION,
});

/**
 * Ответ похож на набор настроек: словарь «ключ → значение».
 *
 * Проверка нарочно грубая — состав ключей задаёт бэк, и требовать здесь
 * конкретные означало бы ломать кэш на каждой новой настройке. Задача
 * проверки одна: не дать массиву или строке-заглушке лечь в кэш вместо
 * настроек.
 *
 * Признак `storedKeys` она пропускает вместе со значениями — так он и
 * попадает в кэш; разбирают его правила отбора (lib/config/app-config-patch),
 * им же битый признак не страшен.
 */
export const isAppSettingsPayload = (value: unknown): boolean =>
    Boolean(value) && typeof value === 'object' && !Array.isArray(value);

/**
 * Явная инвалидация настроек: «в админке щёлкнули переключатель».
 *
 * Запись помечается протухшей, а не удаляется: настройки остаются
 * действовать, пока не приедут новые. Зовётся из кнопки ⟳ (`reloadApp`)
 * вместе с инвалидацией слепка портала.
 */
export const expireAppConfigCache = (domain: string): Promise<boolean> =>
    expireSwrCache(getAppConfigCacheKey(domain));
